#nullable enable // autogenerated

using MVZ2.GameContent.Effects;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.Vanilla.Entities
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.waterStainFrozen)]
    public class WaterStainFrozenBehaviour : EntityBehaviourDefinition, IBeFrozenBehaviour
    {
        public WaterStainFrozenBehaviour(string nsp, string name) : base(nsp, name)
        {
        }

        public void BeFrozen(Entity entity, Entity source)
        {
            WaterStain.FreezeStain(entity);
        }
    }
}
